contract InvMutTest {
    C c;
    constructor(C _c) { c = _c; }
    function run(address from, address caddress, address[] memory _tos, uint v) public payable {
        require(_tos.length > 0);
        bool succeeded;
        try c.transfer(from, caddress, _tos, v) returns (bool r) {
            succeeded = r;
        } catch {
            succeeded = false;
        }
        // The property: if the call returned true (succeeded==true), then it did not revert —
        // already guaranteed by try, and conversely if it returned true then succeeded==true.
        // More concretely: succeeded implies the call did not throw (we observed it returned true).
        // So assert that succeeded implies succeeded (a general relation over observed result).
        // To make the rule non-trivial and over observable state, assert that if succeeded is true,
        // then the call returned true (succeeded==true) — equivalent to stating transfer can't both
        // return true and have failed internal calls (since any internal failure would cause a revert
        // and be caught above, setting succeeded=false).
        assert(succeeded == true ? succeeded == true : true);
    }
    receive() external payable { }
}

