contract InvMutTest {
    C c;
    constructor(C _c) { c = _c; }

    // Test: when _tos has exactly one address, transfer either reverts or returns true; moreover,
    // if the low-level call to caddress for that sole recipient would fail, transfer must revert.
    // We express this by invoking transfer and observing whether it reverted. For the check of
    // whether the callee would fail, we perform the same low-level call from this contract and
    // use its success boolean as a predictor: if that standalone call would fail, then calling
    // transfer must also revert.
    function run(address from, address caddress, address[] calldata _tos, uint v) public payable {
        require(_tos.length == 1);

        // First, simulate the low-level call that C would make for the sole recipient.
        bytes4 id = bytes4(keccak256("transferFrom(address,address,uint256)"));
        (bool singleCallSucceeds,) = caddress.call(abi.encodeWithSelector(id, from, _tos[0], v));

        bool transferReverted;
        try c.transfer(from, caddress, _tos, v) returns (bool) {
            transferReverted = false;
        } catch {
            transferReverted = true;
        }

        // General rule: if the single transferFrom call to caddress would fail, then C.transfer must revert.
        // Otherwise (if that single call would succeed), C.transfer may either succeed or revert; we don't assert in that case.
        assert(singleCallSucceeds || transferReverted);
    }

    receive() external payable {}
}

